CustomField.formula:
TEXT(
  IF( ISPICKVAL( RequestReason , 'Other') , $CustomMetadata.Automated_Request_Purpose__mdt.Other.Duration__c , 
    IF( ISPICKVAL( RequestReason , 'Financial Wellbeing') ,  $CustomMetadata.Automated_Request_Purpose__mdt.Financial_Wellbeing.Duration__c ,
      15)
  )
) & ' Minutes'
